`timescale 1ns/1ps
module counter_12_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;


  reg clk, rst_n, valid_count;
  wire [3:0] out;

  counter_12 dut (
    .rst_n(rst_n),
    .clk(clk),
    .valid_count(valid_count),
    .out(out)
  );

  always #5 clk = ~clk;
  integer i = 0;
  integer error = 0;

  task reset;
    begin
      rst_n = 0;
      valid_count = 0;
      #20;
      rst_n = 1;
      #10; // Stabilize after reset
    end
  endtask

  //--------------------------------------------------
  // 新增 10+ 测试用例
  //--------------------------------------------------

  // 测试用例 4: 计数器满后归零测试
  task test_round4;
    begin
      $display("===== Round 4: Counter Wrap Test =====");
      valid_count = 1;
      #200; // Let counter run 10 cycles (0-11)
      error = (out == 0) ? error : error + 1; // 检查是否归零
    end
  endtask

  // 测试用例 5: 随机暂停/恢复测试
  task test_round5;
    begin
      $display("===== Round 5: Random Toggle Test =====");
      repeat(3) begin
        valid_count = $random;
        #($urandom_range(20,50));
      end
      error = (out != 0) ? error : error; // 确保复位后初始状态
    end
  endtask

  // 测试用例 6: 边界值测试（11 -> 0）
  task test_round6;
    begin
      $display("===== Round 6: 11->0 Transition Test =====");
      valid_count = 1;
      #120; // 刚好到 11
      error = (out == 4'd11) ? error : error + 1;
      #10; // 应该归零
      error = (out == 0) ? error : error + 1;
    end
  endtask

  // 测试用例 7: 连续复位测试
  task test_round7;
    begin
      $display("===== Round 7: Continuous Reset Test =====");
      repeat(3) begin
        reset();
        #10;
      end
      error = (out != 0) ? error : error + 1;
    end
  endtask

  // 测试用例 8: 超长计数测试
  task test_round8;
    begin
      $display("===== Round 8: Long Run Test =====");
      valid_count = 1;
      repeat(50) #10; // 50个周期（应循环4次+余数）
      error = (out == 2) ? error : error + 1; // 50 mod 12 = 2
    end
  endtask

  // 测试用例 9: 无效计数保持测试
  task test_round9;
    begin
      $display("===== Round 9: Invalid Hold Test =====");
      valid_count = 1;
      #30;
      valid_count = 0;
      repeat(5) begin
        error = (out == 3) ? error : error + 1; // 检查是否保持
        #10;
      end
    end
  endtask

  // 测试用例 10: 异步复位测试
  task test_round10;
    begin
      $display("===== Round 10: Async Reset Test =====");
      valid_count = 1;
      #15; // 非时钟边沿复位
      rst_n = 0;
      #5;
      error = (out == 0) ? error : error + 1;
      rst_n = 1;
    end
  endtask

  // 测试用例 11: 上电复位测试
  task test_round11;
    begin
      $display("===== Round 11: Power-On Reset Test =====");
      rst_n = 0;
      valid_count = 1;
      #100;
      error = (out != 0) ? error : error + 1;
    end
  endtask

  // 测试用例 12: 极端时序测试
  task test_round12;
    begin
      $display("===== Round 12: Timing Edge Test =====");
      // 在时钟边沿附近切换 valid_count
      #4 valid_count = 1;
      #1 valid_count = 0;
      #5 valid_count = 1;
      #9 valid_count = 0;
      error = (out == 0) ? error : error + 1;
    end
  endtask

  //--------------------------------------------------
  // 初始块整合所有测试
  //--------------------------------------------------
  initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

    clk = 0;
    rst_n = 0;
    valid_count = 0;

    // 原有测试
    //reset(); test_round1();
   // reset(); test_round2();
    //reset(); test_round3();

    // 新增测试（共12组）
    reset(); test_round4();
    reset(); test_round5();
    reset(); test_round6();
    reset(); test_round7();
    reset(); test_round8();
    reset(); test_round9();
    reset(); test_round10();
    reset(); test_round11();
    reset(); test_round12();

    // Final Check
    if (error == 0) begin
      $display("=========== TEST PASSED ===========");
    end else begin
      $display("=========== TEST FAILED (%d errors) ===========", error);
    end
    $finish;
  end

  // 文件输出（保持不变）
 // integer f;
 // initial begin
 //   f = $fopen("output.txt");
 //   $fwrite(f, "time, out\n");
 //   forever begin
  //    #1;
 //     $fwrite(f, "%0d, %h\n", $time, out);
 //   end
//  end





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "out,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", out);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests (synchronization)
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Mutation Verification Stimuli...");

    // ------------------------------------------------------------
    // Initialization
    // ------------------------------------------------------------
    // Align with negative edge of clock (clk starts 0, toggles at 5, 15...)
    // T=0
    rst_n = 0;
    valid_count = 0;

    // Hold reset for a few cycles
    #20; 

    // ------------------------------------------------------------
    // Test Case 1: Basic Reset Recovery & Full Count Sequence
    // ------------------------------------------------------------
    // Release reset
    rst_n = 1;
    #10;

    // Enable counting
    // Counter should go 0 -> 1 -> ... -> 11 -> 0
    // Pipeline latency is 2 cycles + 1 cycle for count update = 3 cycles visibility
    // We run enough cycles to cover full range and wrap-around
    $display("LLM: Test 1 - Full Count 0->11->0");
    valid_count = 1;
    #200; // 20 clock cycles (200ns)

    // ------------------------------------------------------------
    // Test Case 2: Control Flow - Pause/Resume (Valid Signal)
    // ------------------------------------------------------------
    // Deassert valid_count to check if counter holds value
    // This targets 'if (valid_count)' mutations
    $display("LLM: Test 2 - Pause/Resume");
    valid_count = 0;
    #40; // Hold for 4 cycles

    // Resume counting
    valid_count = 1;
    #40; // Run for 4 cycles

    // ------------------------------------------------------------
    // Test Case 3: Asynchronous Reset Sensitivity
    // ------------------------------------------------------------
    // Assert reset strictly between clock edges to verify async behavior.
    // Clock is Low at T=X0, High at T=X5.
    // We are currently at a multiple of 10 (Low phase).
    // Pulse reset low for 2ns (shorter than clock phase)
    // If reset is synchronous (mutation), this pulse might be ignored or behave differently.
    $display("LLM: Test 3 - Async Reset Glitch");
    rst_n = 0;
    #2;
    rst_n = 1;
    #8; // Re-align to 10ns grid

    // Verify recovery
    #30;

    // ------------------------------------------------------------
    // Test Case 4: Boundary Wrap-Around Stress
    // ------------------------------------------------------------
    // Reset and run exactly to the boundary (11)
    $display("LLM: Test 4 - Boundary Wrap Specifics");
    rst_n = 0; 
    #10; 
    rst_n = 1;

    // 0 -> 11 takes 11 posedges. 11 * 10ns = 110ns.
    valid_count = 1;
    #110; 

    // At this point, internal cnt should be 11.
    // Pause here to verify state 11 is held.
    valid_count = 0;
    #20;

    // Resume to force wrap 11 -> 0
    valid_count = 1;
    #20;

    // ------------------------------------------------------------
    // Test Case 5: Rapid Toggle (Stress Test)
    // ------------------------------------------------------------
    // Toggle valid_count every cycle to expose potential edge/level sensitivity mutations
    $display("LLM: Test 5 - Rapid Toggle");
    for (i = 0; i < 6; i = i + 1) begin
        valid_count = ~valid_count;
        #10;
    end
    valid_count = 0;
    #20;

    // ------------------------------------------------------------
    // Test Case 6: Pipeline Flush
    // ------------------------------------------------------------
    // Fill pipeline with non-zero values then reset
    valid_count = 1;
    #50;
    rst_n = 0;
    #10;
    rst_n = 1;
    #20;

    // 4. Handover to Original Testbench
    $display("LLM: Stimuli Finished. Handing over.");
    llm_go_signal = 0;

    // Note: Do NOT close file handles or finish simulation here.
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

